package tech.kayys.numou.content.application.media;
import org.junit.jupiter.api.Test;
import tech.kayys.numou.content.application.ContentCommandContext;
import tech.kayys.numou.content.domain.*;
import tech.kayys.numou.content.domain.media.*;
import tech.kayys.numou.content.spi.*;
import java.time.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class MediaApplicationServiceTest {
 static class Assets implements MediaAssetRepository {Map<MediaAssetId,MediaAsset> map=new HashMap<>();public void create(MediaAsset a){map.put(a.id(),a);}public Optional<MediaAsset> find(TenantId t,MediaAssetId id){var a=map.get(id);return a!=null&&a.tenantId().equals(t)?Optional.of(a):Optional.empty();}public Optional<MediaAsset> findByDocumentVersion(TenantId t,String d,String v){return map.values().stream().filter(a->a.tenantId().equals(t)&&a.documentId().equals(d)&&a.documentVersionId().equals(v)).findFirst();}public boolean update(MediaAsset a,MediaScanStatus s,MediaLifecycleStatus l){var old=map.get(a.id());if(old==null||old.scanStatus()!=s||old.status()!=l)return false;map.put(a.id(),a);return true;}}
 static class References implements ContentMediaReferenceRepository {List<ContentMediaReference> values=new ArrayList<>();public boolean attach(ContentMediaReference r){values.add(r);return true;}public boolean detach(TenantId t,UUID id){return values.removeIf(r->r.tenantId().equals(t)&&r.id().equals(id));}public List<ContentMediaReference> findByContent(TenantId t,ContentId id,int rev){return values.stream().filter(r->r.tenantId().equals(t)&&r.contentId().equals(id)&&r.revisionNumber()==rev).toList();}}
 @Test void blocksAttachUntilCleanAndScopesMediaByTenant(){var assets=new Assets();var refs=new References();var content=new ContentRepository(){public void create(ContentEntry e){}public Optional<ContentEntry> find(TenantId t,ContentId id){return Optional.of(ContentEntry.create(t,"Title","title","{}",tech.kayys.numou.content.domain.model.ContentTypeId.newId(),1,new ActorId(UUID.randomUUID()),Instant.now()));}public boolean appendRevision(ContentEntry e,int n){return false;}public boolean transitionStatus(TenantId t,ContentId id,ContentStatus a,ContentStatus b,Instant i){return false;}};var service=new MediaApplicationService(assets,refs,content,Clock.systemUTC());var tenant=new TenantId(UUID.randomUUID());var actor=new ActorId(UUID.randomUUID());var ctx=new ContentCommandContext(tenant,actor);var media=service.registerUploadedDocument(ctx,"doc","version","image.jpg","image/jpeg",MediaKind.IMAGE,12,"b".repeat(64));var contentId=ContentId.newId();assertThrows(IllegalStateException.class,()->service.attach(ctx,media.id(),contentId,1,"featured"));service.recordScanVerdict(ctx,media.id(),MediaScanStatus.CLEAN);assertEquals(1,service.attach(ctx,media.id(),contentId,1,"featured").revisionNumber());assertTrue(refs.values.size()==1);var eventHandler=new DocumentMediaScanEventHandler(service);assertEquals(MediaLifecycleStatus.AVAILABLE,eventHandler.handle(new DocumentMediaScanEvent(tenant.toString(),"doc","version","CLEAN")).status());}
}
